import { Black_Han_Sans, Noto_Sans_KR, Orbitron } from "next/font/google";

export const blackHanSans = Black_Han_Sans({
  weight: "400",
  subsets: ["latin"],
  variable: "--font-black-han",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

export const orbitron = Orbitron({
  weight: ["400", "700", "900"],
  subsets: ["latin"],
  variable: "--font-orbitron",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

/* ==========================================================================
   NEON 네온 — rain-slick cyberpunk city · 2087
   vaporwave · rain-black / magenta / cyan / purple · neon glow + rain
   Scoped by convention to .neon-root; classes prefixed neon-.
   ========================================================================== */

.neon-root {
  --neon-bg: #0a0612;
  --neon-deep: #05030a;
  --neon-magenta: #ff2d95;
  --neon-cyan: #00f0ff;
  --neon-purple: #b026ff;
  --neon-sign-white: #f0f0ff;
  --neon-dim: #6b4a7a;

  --neon-font-display: var(--font-black-han), "Black Han Sans", sans-serif;
  --neon-font-kr: var(--font-noto-sans-kr), "Noto Sans KR", sans-serif;
  --neon-font-latin: var(--font-orbitron), "Orbitron", sans-serif;
  --neon-font-stack: var(--font-orbitron), var(--font-noto-sans-kr), sans-serif;

  --neon-ease: cubic-bezier(0.16, 1, 0.3, 1);

  position: relative;
  min-height: 100vh;
  background: var(--neon-bg);
  background-image: linear-gradient(180deg, var(--neon-deep) 0%, var(--neon-bg) 60%, #160a2e 100%);
  color: var(--neon-sign-white);
  font-family: var(--neon-font-stack);
  font-weight: 400;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.7;
  overflow-x: hidden;
  overflow-x: clip;
}

.neon-root :lang(ko) {
  font-family: var(--neon-font-kr);
}

.neon-root ::selection {
  background: var(--neon-magenta);
  color: var(--neon-bg);
}

.neon-root :focus-visible {
  outline: 2px solid var(--neon-cyan);
  outline-offset: 4px;
}

.neon-js [data-reveal] {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 800ms var(--neon-ease), transform 800ms var(--neon-ease);
}
.neon-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  .neon-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

.neon-doc { position: relative; z-index: 2; }

/* Hero */
.neon-hero {
  padding: clamp(80px, 18vh, 160px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 80px);
  text-align: center;
}
.neon-kicker {
  font-family: var(--neon-font-latin);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.25em;
  color: var(--neon-cyan);
  margin: 0 0 30px;
}
.neon-title {
  font-family: var(--neon-font-latin);
  font-weight: 900;
  font-size: clamp(4rem, 16vw, 12rem);
  line-height: 0.9;
  margin: 0 0 20px;
}
.neon-title__glow {
  color: var(--neon-magenta);
  text-shadow:
    0 0 8px var(--neon-magenta),
    0 0 20px var(--neon-magenta),
    0 0 40px rgba(255,45,149,0.5);
}
.neon-title__kr {
  display: block;
  font-family: var(--neon-font-display);
  font-size: 0.35em;
  color: var(--neon-cyan);
  text-shadow: 0 0 10px var(--neon-cyan);
  margin-top: 12px;
}
.neon-sub {
  color: var(--neon-dim);
  font-size: clamp(0.9rem, 1.6vw, 1.1rem);
  margin: 0;
}

/* Signs */
.neon-signs {
  padding: clamp(60px, 12vh, 120px) clamp(20px, 5vw, 60px);
  border-top: 1px solid rgba(176,38,255,0.2);
}
.neon-secthead {
  font-family: var(--neon-font-latin);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--neon-purple);
  margin: 0 0 50px;
  text-align: center;
}
.neon-signgrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(24px, 4vw, 48px);
  max-width: 900px;
  margin: 0 auto;
}
.neon-sign {
  text-align: center;
  padding: 30px 16px;
}
.neon-sign__ascii {
  font-family: monospace;
  font-size: clamp(0.7rem, 1.2vw, 0.9rem);
  line-height: 1.3;
  white-space: pre;
  display: inline-block;
  text-align: left;
  margin: 0 0 16px;
}
.neon-sign--magenta .neon-sign__ascii {
  color: var(--neon-magenta);
  text-shadow: 0 0 6px var(--neon-magenta), 0 0 14px rgba(255,45,149,0.4);
}
.neon-sign--cyan .neon-sign__ascii {
  color: var(--neon-cyan);
  text-shadow: 0 0 6px var(--neon-cyan), 0 0 14px rgba(0,240,255,0.4);
}
.neon-sign--purple .neon-sign__ascii {
  color: var(--neon-purple);
  text-shadow: 0 0 6px var(--neon-purple), 0 0 14px rgba(176,38,255,0.4);
}
.neon-sign__cap {
  font-family: var(--neon-font-display);
  font-size: 1.1rem;
  margin: 0;
  opacity: 0.8;
}

/* Marquee */
.neon-marquee {
  overflow: hidden;
  padding: 14px 0;
  border-top: 1px solid rgba(176,38,255,0.2);
  border-bottom: 1px solid rgba(176,38,255,0.2);
  white-space: nowrap;
}
.neon-marquee__track {
  display: inline-block;
  font-family: var(--neon-font-latin);
  font-size: 0.8rem;
  color: var(--neon-cyan);
  animation: neon-marquee 30s linear infinite;
  padding-left: 100%;
}
@keyframes neon-marquee { to { transform: translateX(-100%); } }
@media (prefers-reduced-motion: reduce) {
  .neon-marquee__track { animation: none; padding-left: 0; }
}

/* Footer */
.neon-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  color: var(--neon-dim);
  font-size: 0.8rem;
  text-align: center;
}
.neon-foot p { margin: 0 0 6px; }

/* Rain overlay — diagonal lines */
.neon-rain {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    105deg,
    transparent 0px,
    transparent 3px,
    rgba(0,240,255,0.04) 3px,
    rgba(0,240,255,0.04) 4px
  );
  animation: neon-rain 0.6s linear infinite;
}
@keyframes neon-rain {
  to { background-position: 0 20px; }
}
@media (prefers-reduced-motion: reduce) {
  .neon-rain { animation: none; opacity: 0.5; }
}

/* Scanlines */
.neon-scanlines {
  position: fixed;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent 0px,
    transparent 2px,
    rgba(0,0,0,0.15) 2px,
    rgba(0,0,0,0.15) 3px
  );
}
